from collections import deque

class Solution:
    def minimumOperations(self, nums: List[int], start: int, goal: int) -> int:
        q = deque([start])
        seen = {start}
        steps = 0
        while q:
            for _ in range(len(q)):
                x = q.popleft()
                for v in nums:
                    for y in (x + v, x - v, x ^ v):
                        if y == goal:
                            return steps + 1
                        if 0 <= y <= 1000 and y not in seen:
                            seen.add(y)
                            q.append(y)
            steps += 1
        return -1

