class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        int[] dist = new int[1001];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> q = new ArrayDeque<>();
        q.offer(start);
        while (!q.isEmpty()) {
            int x = q.poll();
            for (int v : nums)
                for (long y : new long[]{(long) x + v, (long) x - v, (long)(x ^ v)}) {
                    if (y == goal) return dist[x] + 1;
                    if (y >= 0 && y <= 1000 && dist[(int) y] == -1) {
                        dist[(int) y] = dist[x] + 1;
                        q.offer((int) y);
                    }
                }
        }
        return -1;
    }
};

