import heapq

class Solution:
    def minimumOperations(self, nums: List[int], start: int, goal: int) -> int:
        INF = float('inf')
        dist = {start: 0}
        pq = [(0, start)]
        while pq:
            d, x = heapq.heappop(pq)
            if x == goal:
                return d
            if d > dist[x]:
                continue
            for v in nums:
                for y in (x + v, x - v, x ^ v):
                    if y != goal and not (0 <= y <= 1000):
                        continue
                    if d + 1 < dist.get(y, INF):
                        dist[y] = d + 1
                        heapq.heappush(pq, (d + 1, y))
        return -1

