class Solution {
public:
    int minimumOperations(vector<int>& nums, int start, int goal) {
        unordered_map<long long, long long> dist;
        priority_queue<pair<long long, long long>,
                       vector<pair<long long, long long>>,
                       greater<>> pq;
        dist[start] = 0;
        pq.emplace(0, start);
        while (!pq.empty()) {
            auto [d, x] = pq.top();
            pq.pop();
            if (x == goal) return (int)d;
            if (d > dist[x]) continue;
            for (int v : nums)
                for (long long y : {(long long)x + v, (long long)x - v, (long long)((long long)x ^ v)}) {
                    if (y != goal && (y < 0 || y > 1000)) continue;
                    auto it = dist.find(y);
                    if (it == dist.end() || d + 1 < it->second) {
                        dist[y] = d + 1;
                        pq.emplace(d + 1, y);
                    }
                }
        }
        return -1;
    }
};

