class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        Map<Long, Long> dist = new HashMap<>();
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        dist.put((long) start, 0L);
        pq.offer(new long[]{0, start});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0], x = top[1];
            if (x == goal) return (int) d;
            if (d > dist.get(x)) continue;
            for (int v : nums)
                for (long y : new long[]{x + v, x - v, x ^ v}) {
                    if (y != goal && (y < 0 || y > 1000)) continue;
                    Long old = dist.get(y);
                    if (old == null || d + 1 < old) {
                        dist.put(y, d + 1);
                        pq.offer(new long[]{d + 1, y});
                    }
                }
        }
        return -1;
    }
};

