var minimumOperations = function(nums, start, goal) {
    class MinHeap {
        constructor() { this.a = []; }
        size() { return this.a.length; }
        push(x) {
            this.a.push(x);
            let i = this.a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.a[p][0] <= this.a[i][0]) break;
                [this.a[p], this.a[i]] = [this.a[i], this.a[p]];
                i = p;
            }
        }
        pop() {
            const top = this.a[0];
            const last = this.a.pop();
            if (this.a.length) {
                this.a[0] = last;
                let i = 0;
                for (;;) {
                    const l = 2 * i + 1, r = l + 1;
                    let m = i;
                    if (l < this.a.length && this.a[l][0] < this.a[m][0]) m = l;
                    if (r < this.a.length && this.a[r][0] < this.a[m][0]) m = r;
                    if (m === i) break;
                    [this.a[m], this.a[i]] = [this.a[i], this.a[m]];
                    i = m;
                }
            }
            return top;
        }
    }
    const dist = new Map();
    const heap = new MinHeap();
    dist.set(start, 0);
    heap.push([0, start]);
    while (heap.size()) {
        const [d, x] = heap.pop();
        if (x === goal) return d;
        if (d > dist.get(x)) continue;
